import {AFFECT_COMPONENTS,getAffectForms} from './affect-components.mjs';
// Independently authored native HTML adaptations. Upstream React packages are not runtime dependencies.
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
const btn=(text,action='notice',extra='')=>`<button type="button" class="kv-button" data-kv-action="${action}" ${extra}>${text}</button>`;
const muted=s=>`<p class="kv-muted">${s}</p>`;
const head=(title,sub='')=>`<header class="kv-heading"><strong>${title}</strong>${sub?muted(sub):''}</header>`;
const badge=s=>`<span class="kv-badge">${s}</span>`;
const row=(a,b)=>`<div class="kv-row"><span>${a}</span><span>${b}</span></div>`;
const panel=(a,b='')=>`<section class="kv-panel">${head(a)}${b}</section>`;
const field=(label,type='text',value='',attrs='')=>`<label class="kv-field"><span>${label}</span><input type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,items)=>`<label class="kv-field"><span>${label}</span><select>${items.map(x=>`<option>${x}</option>`).join('')}</select></label>`;
const checks=(items,kind='checkbox',name='option',cards=false)=>`<fieldset class="kv-choices ${cards?'kv-choice-cards':''}"><legend>${kind==='radio'?'한 가지 선택':'필요한 항목 선택'}</legend>${items.map((x,i)=>`<label><input type="${kind}" name="${esc(name)}" value="${esc(x.split('|')[0])}" ${i===0?'checked':''}><span><strong>${x.split('|')[0]}</strong>${x.includes('|')?`<small>${x.split('|')[1]}</small>`:''}</span></label>`).join('')}</fieldset>`;
const progress=(value,label='완료')=>`<label class="kv-progress-label">${label}<span>${value}%</span><progress max="100" value="${value}">${value}%</progress></label>`;
const list=(items)=>`<ul class="kv-list">${items.map(s=>`<li>${s}</li>`).join('')}</ul>`;
const details=(title,body,open=false)=>`<details class="kv-details" ${open?'open':''}><summary>${title}</summary><div>${body}</div></details>`;
const submit=(label='저장')=>`<button class="kv-button kv-primary" type="submit">${label}</button><output class="kv-output" aria-live="polite"></output>`;
const form=(body,label='저장')=>`<form data-kv-form>${body}${submit(label)}</form>`;
const table=(heads,rows,attrs='')=>`<div class="kv-table-scroll" tabindex="0" role="region" aria-label="데이터 표"><table ${attrs}><thead><tr>${heads.map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const avatar=(s='김')=>`<span class="kv-avatar" aria-label="${s}">${s}</span>`;
const tabs=(uid,labels,contents,vertical=false)=>`<div class="kv-tabs ${vertical?'kv-tabs-vertical':''}"><div role="tablist" aria-label="보기" ${vertical?'aria-orientation="vertical"':''}>${labels.map((s,i)=>`<button type="button" role="tab" id="${uid}-tab-${i}" aria-controls="${uid}-panel-${i}" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-kv-action="tab">${s}</button>`).join('')}</div>${contents.map((s,i)=>`<section role="tabpanel" id="${uid}-panel-${i}" aria-labelledby="${uid}-tab-${i}" ${i?'hidden':''}>${s}</section>`).join('')}</div>`;
const menu=(title,items)=>details(title,`<div class="kv-menu">${items.map(s=>typeof s==='string'&&!s.startsWith('<')?btn(s):s).join('')}</div>`);
const dialog=(uid,title,content,trigger='열기',kind='')=>`${btn(trigger,'open',`data-kv-target="${uid}-dialog"`)}<dialog id="${uid}-dialog" aria-label="${esc(title)}" class="kv-dialog ${kind}">${head(title)}${content}<footer class="kv-actions">${btn('닫기','close')}</footer></dialog>`;
const metric=(label,value,sub='')=>`<div class="kv-metric"><span>${label}</span><strong>${value}</strong>${muted(sub)}</div>`;
const spark=(vals=[40,33,38,21,29,12,17,8])=>`<svg class="kv-spark" viewBox="0 0 180 56" role="img" aria-label="기간별 추세: ${vals.join(', ')}"><polyline points="${vals.map((v,i)=>`${i*25},${v}`).join(' ')}" fill="none" stroke="currentColor" stroke-width="3"/></svg>`;
const art=(title='새로운 연결',mode='')=>`<div class="kv-art ${mode}" role="img" aria-label="${title}"><span>KLIC</span><strong>${title}</strong><span class="kv-art-orbit"></span></div>`;
const defs={};
const add=(id,forms)=>{defs[id]=forms;};
const v=(id,name,description,render)=>({id,name,description,render});

add('button',[
v('leading-icon','아이콘 동작','아이콘과 설명으로 생성 행동의 목적을 명확하게 안내합니다.',u=>`${head('팀의 다음 작업을 시작하세요','프로젝트 생성 후 멤버를 초대할 수 있습니다.')}<div class="kv-actions">${btn(`${icon('plus')} 새 프로젝트`,'notice','data-kv-message="새 프로젝트 초안이 준비되었습니다."')}${btn(`${icon('upload')} 파일 가져오기`)}</div>`),
v('split-action','분할 실행','기본 실행과 추가 실행 옵션을 하나의 그룹으로 묶습니다.',u=>`${head('보고서 배포','가장 자주 쓰는 실행을 앞에 배치합니다.')}<div class="kv-actions kv-joined">${btn(`${icon('send')} 지금 발송`)}${menu('추가 옵션',['예약 발송','초안 저장','미리 보기'])}</div>`),
v('confirmation','확인형 동작','중요한 동작 전에 한 번 더 확인하는 인라인 단계를 제공합니다.',u=>`${head('사용하지 않는 초안','삭제를 누르면 확인 단계가 표시됩니다.')}<div data-kv-confirm>${btn(`${icon('trash-2')} 초안 삭제`,'confirm')}<div hidden data-kv-confirm-panel>${muted('이 미리 보기의 초안을 삭제할까요?')}${btn('삭제 확인','confirmed')}${btn('취소','cancel-confirm')}</div><output class="kv-output" aria-live="polite"></output></div>`),
v('icon-tools','아이콘 단독 작업','이름이 있는 아이콘 단독 버튼과 상세 도움말을 결합한 도구 모음입니다.',u=>`${head('문서 도구','자주 사용하는 작업을 작은 아이콘으로 배치합니다.')}<div class="kv-icon-tools">${[['bookmark','관심 문서'],['pin','상단 고정'],['bell','알림 받기']].map(([i,s])=>`<div>${btn(icon(i),'toggle',`aria-pressed="false" aria-label="${s}" title="${s}"`)}<small>${s}</small></div>`).join('')}</div>${details('아이콘 안내',muted('관심 문서에 저장하거나 상단에 고정하고 알림을 받을 수 있습니다. 각 선택은 독립적으로 유지됩니다.'))}`)
]);
add('button-group',[
v('editor','편집 도구','서식 토글과 별도의 초기화 행동으로 문서 도구를 구성합니다.',u=>`${head('문서 서식')}<div class="kv-actions kv-joined" role="group" aria-label="문서 서식">${['굵게','기울임','밑줄'].map(s=>btn(s,'toggle','aria-pressed="false"')).join('')}</div>${muted('각 서식은 독립적으로 켜고 끌 수 있습니다.')}`),
v('split-publish','게시 분할 버튼','게시 기본 동작과 예약 옵션을 분리합니다.',u=>`${head('변경 사항 3건','모든 변경은 로컬 미리 보기입니다.')}<div class="kv-actions kv-joined">${btn('변경 게시')}${menu('게시 옵션',['내일 게시','초안 보관'])}</div>`),
v('step-controls','단계 이동 그룹','뒤로·다음과 현재 단계를 함께 제공하는 순차 탐색입니다.',u=>`<div data-kv-stepper>${head('워크스페이스 설정')}<ol class="kv-step-list"><li data-kv-step>기본 정보</li><li data-kv-step hidden>멤버 초대</li><li data-kv-step hidden>설정 검토</li></ol><div class="kv-actions">${btn('이전','step-prev')}${btn('다음','step-next')}</div><output class="kv-output" aria-live="polite">1 / 3</output></div>`),
v('bulk-actions','일괄 선택 동작','선택된 항목 수와 적용할 작업을 같은 바에 배치합니다.',u=>`${checks(['디자인 가이드','운영 매뉴얼'],'checkbox',u)}<div class="kv-actions">${btn('선택 항목 보관','selection-action')}${btn('선택 해제','uncheck')}</div><output class="kv-output" aria-live="polite"></output>`)
]);
// Input families deliberately model different jobs, not different border colors.
