export function getAddedVariants(id,uid='example') {
 if(AFFECT_COMPONENTS.some(c=>c.id===id))return getAffectForms(id,uid).slice(1);
 const forms=defs[id]; if(!forms)return [];
 const safe=Array.from(String(uid)).map(c=>/[a-zA-Z0-9-]/.test(c)?c:'_'+c.codePointAt(0).toString(16)+'_').join('');
 return forms.map((f,index)=>{const key=`kv-${safe}-${id}-${f.id}`;return {id:f.id,name:f.name,description:f.description,html:`<div class="kv-demo kv-family-${id} kv-form-${f.id}" data-kv-root data-klic-material="surface" data-kv-component="${id}" data-kv-variant="${f.id}">${f.render(key).replace(/class="(kv-(?:panel|card|dialog|input-group|button|floating-panel|context-menu|bar-popup|confirm-pop|hover-content))(?=[ "])/g,(match,klass,offset,html)=>html.slice(offset).startsWith('class="kv-button kv-primary')?match:`data-klic-surface="${({'kv-panel':'card','kv-card':'card','kv-dialog':'overlay','kv-input-group':'field','kv-button':'control','kv-floating-panel':'overlay','kv-context-menu':'overlay','kv-bar-popup':'overlay','kv-confirm-pop':'overlay','kv-hover-content':'overlay'})[klass]}" ${match}`)}</div>`,reference:variantReferences[id][index]};});
}
